mapper.update:
                UPDATE SMT_LEAVE_APPLICATION SLA
				SET SLA.APPROVE_STATUS = #{approveStatus}
				WHERE
				    SLA.PROCESS_ID = #{processId}

mapper.select:
SELECT SLA. ID, SLA.PARK_ID, SLA.BADGE, SLA. NAME, SLA.COMP_ID, SLA.COMP_NAME, SLA.DEP_ID, SLA.DEP_NAME, SLA.JCHEN_ID, SLA.JCHEN_NAME, SLA.LEAVE_TYPE, SLA.LEAVE_REASON, SLA.YEAR_HOLIDAY, SLA.PROCESS_ID, SLA.JOIN_TIME, SLA.LEAVE_TIME, SLA.CREATE_TIME, SLA.EZID, SLA.JOB_ID, SLA.JOB_NAME, SLA.LEAVE_STATUS, SLA.APPROVE_STATUS, SLA.APPLY_BADGE, SLA.EID FROM SMT_LEAVE_APPLICATION SLA
AND SLA.NAME LIKE CONCAT(CONCAT('%',#{query.name}),'%')
AND SLA.BADGE = #{query.badge}
AND SLA.COMP_ID IN ( SELECT DISTINCT SPB.COMP_ID from SMT_PARK_BU SPB
SPB.PARK_ID IN
#{id}
)
AND TO_DATE(TO_CHAR(SLA.LEAVE_TIME, 'YYYY-MM-DD'),'YYYY-MM-DD') >= TO_DATE(#{query.startTime,jdbcType=DATE}, 'yyyy-MM-dd')
AND TO_DATE(TO_CHAR(SLA.LEAVE_TIME, 'YYYY-MM-DD'),'YYYY-MM-DD') <= TO_DATE(#{query.endTime,jdbcType=DATE}, 'yyyy-MM-dd')
ORDER BY SLA.CREATE_TIME DESC
